import {DATA} from './data.js';
import {CORE, createSession, examQuestions, scoreSession, remainingSeconds} from './engine.js';

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY = 'patternlab-v1';
const emptyState = () => ({read:[], outcomes:{}, history:[], session:null, result:null});
let state = emptyState(), storageOK = true;
try {
  const raw = JSON.parse(localStorage.getItem(KEY) || 'null');
  if (raw && Array.isArray(raw.read) && raw.outcomes && Array.isArray(raw.history)) state = {...state,...raw};
} catch { storageOK = false; }
let filter = {text:'',topic:'all'}, toastTimer;
const questionsById = new Map(DATA.questions.map(q => [q.id,q]));
const icons = {1:'{ }',5:'⊕',6:'↗',7:'⇄',8:'◎'};

function save() {
  try {localStorage.setItem(KEY,JSON.stringify(state));}
  catch {storageOK=false; toast('Браузер не сохраняет прогресс. Текущая сессия продолжит работать.');}
}
function toast(text) {
  $('#toast').textContent=text; $('#toast').style.display='block';
  clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);
}
function go(route) { if(location.hash==='#'+route) render(); else location.hash=route; }
function button(text, action, value='', kind='') {
  return `<button class="button ${kind}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
}
function wrongQuestions() {return DATA.questions.filter(q=>state.outcomes[q.id]?.correct===false);}
function masteredCount(){return Object.values(state.outcomes).filter(x=>x.correct).length;}
function resumeBanner(){return state.session ? `<div class="resume"><span><strong>Есть незавершённый квиз</strong><br>${esc(state.session.title)} · ${Object.keys(state.session.answers).length}/${state.session.questions.length} ответов</span>${button('Продолжить →','resume','','primary')}</div>`:'';}
function intro(label,title,description){return `<div class="page-intro"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${description}</p></div>`;}
function lectureCard(l){return `<a class="card interactive" href="#lecture/${l.id}"><div class="card-top"><span class="tile">${icons[l.number]}</span><span class="tag ${state.read.includes(l.id)?'green':''}">${state.read.includes(l.id)?'✓ ПРОЧИТАНО':'ЛЕКЦИЯ '+l.number}</span></div><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p><div class="card-bottom"><span>${l.minutes} мин чтения · конспект</span><span class="arrow">↗</span></div></a>`;}
function examCard(){return `<aside class="exam-card"><div class="eyebrow">ПРОВЕРЬ СЕБЯ</div><h2>Репетиция<br>финального MCQ</h2><div class="exam-numbers"><div><strong>30</strong><span>вопросов</span></div><div><strong>50</strong><span>минут</span></div><div><strong>5</strong><span>паттернов</span></div></div><p class="small muted">Без подсказок. Ответы и разбор — после завершения.</p>${button('Начать пробный экзамен →','exam','','primary')}</aside>`;}
function home(){return `${resumeBanner()}<section class="hero"><div class="hero-copy"><div class="eyebrow">ТВОЯ ПОДГОТОВКА К ФИНАЛУ</div><h1>Разберись в паттернах.<br><span class="accent">Проверь себя.</span></h1><p>Самое важное из лекций, ваши квизы и новые задания. Читай, практикуйся и возвращайся к тому, что пока не получилось.</p><div class="actions"><a class="button primary" href="#lectures">Открыть конспекты ↗</a><a class="button" href="#quizzes">Перейти к квизам</a></div></div>${examCard()}</section><div class="stats"><div class="stat"><strong>${DATA.lectures.length}</strong><span>кратких<br>конспектов</span></div><div class="stat"><strong>${DATA.questions.length}</strong><span>вопросов<br>с объяснениями</span></div><div class="stat"><strong>${state.read.length}/5</strong><span>лекций<br>прочитано</span></div><div class="stat"><strong>${masteredCount()}</strong><span>вопросов<br>отвечено верно*</span></div></div><div class="section-head"><h2>Начни с понимания</h2><a href="#lectures">Все лекции →</a></div><div class="grid">${DATA.lectures.slice(0,3).map(lectureCard).join('')}</div><div class="section-head"><h2>Выбери свой темп</h2></div><div class="grid"><a class="card interactive" href="#quizzes"><span class="tag purple">ПРАКТИКА</span><h3>Ваши 4 квиза</h3><p>160 вопросов из прикреплённых файлов. Объяснение после каждого ответа.</p><div class="card-bottom"><span>Вопросы на английском</span><span class="arrow">→</span></div></a><a class="card interactive" href="#quizzes/generated"><span class="tag purple">НОВЫЕ ЗАДАНИЯ</span><h3>По материалам лекций</h3><p>${DATA.questions.filter(q=>q.origin==='generated').length} новых вопросов: роли классов, результат кода и ошибки проектирования.</p><div class="card-bottom"><span>Разбор на русском</span><span class="arrow">→</span></div></a><a class="card interactive" href="#progress"><span class="tag green">ПОВТОРЕНИЕ</span><h3>Работа над ошибками</h3><p>Все сложные вопросы собираются в отдельную подборку. Верный ответ убирает вопрос из ошибок.</p><div class="card-bottom"><span>${wrongQuestions().length} вопросов для повторения</span><span class="arrow">→</span></div></a></div><div class="info-strip"><strong>Что входит в финал?</strong> По выданному заданию: Builder, Decorator, Strategy, Observer и Facade. В старых квизах есть и другие темы — они остаются в общей практике. Пробный экзамен берёт по 6 вопросов на каждый из пяти паттернов; это наша тренировочная подборка, а не официальный банк экзамена.<br><span class="small">* По последнему проверенному ответу на каждый вопрос. Экзамен: 30 вопросов, 50 минут, один ответ, без штрафа; максимум 80 баллов. Источник: Final Project Student Guide.</span></div>`;}
function lectures(){return `${intro('КОРОТКО И ПО ДЕЛУ','Лекции без лишнего','Пять конспектов по прикреплённым PDF. Основные идеи, роли классов, небольшой Java-пример и ловушки в вопросах.')}<div class="grid lecture-grid">${DATA.lectures.map(lectureCard).join('')}</div><div class="info-strip">Это краткое изложение, а не полные слайды. Разделы Clean Code включены в конспекты соответствующих лекций. Номера лекций сохранены из ваших файлов: 1, 5, 6, 7, 8.</div>`;}
function lecture(id){const l=DATA.lectures.find(l=>l.id===id);if(!l)return notFound();return `<div class="reading-layout"><aside class="reading-nav"><div class="eyebrow">КОНСПЕКТЫ</div>${DATA.lectures.map(x=>`<a href="#lecture/${x.id}" class="${x.id===id?'active':''}">${x.number}. ${esc(x.title.split(' и ')[0])}</a>`).join('')}</aside><article class="reading"><a href="#lectures" class="back">← Все лекции</a>${intro(`ЛЕКЦИЯ ${l.number} · ${l.minutes} МИН`,esc(l.title),esc(l.summary))}${l.sections.map(s=>`<section class="note-section"><h2>${esc(s.title)}</h2>${s.body?`<p>${esc(s.body)}</p>`:''}${s.bullets?.length?`<ul>${s.bullets.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${s.code?`<pre class="code"><code>${esc(s.code)}</code></pre>`:''}</section>`).join('')}<div class="source-note">Краткий пересказ: ${esc(l.source)}, страницы ${esc(l.pages)}. Примеры и тренировочные вопросы подготовлены для сайта.</div><div class="note-end">${button(state.read.includes(id)?'✓ Прочитано — отменить отметку':'Отметить как прочитанное','read',id)}${button('Проверить знания →','lecture-quiz',id,'primary')}</div></article></div>`;}
function quizCard(title,desc,count,action,value,badge){return `<div class="card"><div class="card-top"><span class="tile">?</span><span class="tag">${badge}</span></div><h3>${esc(title)}</h3><p>${esc(desc)}</p><div class="card-bottom"><span>${count} вопросов</span>${button('Начать →',action,value)}</div></div>`;}
function quizzes(generatedOnly=false){const topics=[...new Set(DATA.questions.map(q=>q.topic))].sort();return `${resumeBanner()}${intro('ПРАКТИКА','Понимание приходит с практикой','Выбирай ответ, нажимай «Проверить» и читай объяснение. Порядок вопросов и вариантов меняется при каждом запуске.')}<div class="filters"><input id="search" type="search" placeholder="Найти вопрос или фрагмент кода…" aria-label="Поиск вопросов" value="${esc(filter.text)}"><select id="topic" aria-label="Тема вопроса"><option value="all">Все темы</option>${topics.map(t=>`<option value="${esc(t)}" ${filter.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div id="filtered-questions"></div>${!generatedOnly?`<div class="section-head"><h2>Ваши прикреплённые квизы</h2><span class="small muted">4 набора · 160 вопросов</span></div><div class="grid">${DATA.sets.map(s=>quizCard(s.title,s.description,s.count,'set',s.id,'ИЗ ВАШИХ ФАЙЛОВ')).join('')}</div><div class="info-strip">В первом квизе (Adapter) ключ не был указан: ответы восстановлены при подготовке сайта и помечены в разборе. В остальных трёх использован ключ из прикреплённого feedback; объяснения изложены на русском.</div>`:''}<div class="section-head"><h2>Новые вопросы по лекциям</h2>${generatedOnly?'<a href="#quizzes">Все квизы →</a>':''}</div><div class="grid">${DATA.lectures.map(l=>quizCard(l.title,'Новые задания по основным и дополнительным темам лекции.',DATA.questions.filter(q=>q.lecture===l.id).length,'lecture-quiz',l.id,'ЛЕКЦИЯ '+l.number)).join('')}</div><div class="section-head"><h2>Финальные пять паттернов</h2></div><div class="two-col">${quizCard('Смешанная практика','Builder, Decorator, Strategy, Observer и Facade. Без таймера, с объяснениями.',DATA.questions.filter(q=>q.finalCore&&CORE.includes(q.topic)).length,'core','','ФОКУС НА ФИНАЛ')}${examCard()}</div>`;}
function filteredQuestions(){const root=$('#filtered-questions');if(!root)return;const active=filter.text.trim()||filter.topic!=='all';if(!active){root.innerHTML='';return;}const list=filterPool();root.innerHTML=`<div class="info-strip"><strong>Найдено: ${list.length}</strong> ${list.length?button('Практиковать найденные','filtered','','primary'):''}</div>${list.slice(0,12).map(q=>`<div class="card" style="margin-bottom:10px"><span class="tag">${esc(q.topic)}</span><p style="margin:10px 0">${esc(q.prompt.slice(0,220))}${q.prompt.length>220?'…':''}</p>${button('Открыть вопрос','single',q.id)}</div>`).join('')}${list.length>12?'<p class="small muted">Показаны первые 12. В тренировку войдут все найденные вопросы.</p>':''}`;}
function filterPool(){const needle=filter.text.trim().toLowerCase();return DATA.questions.filter(q=>(filter.topic==='all'||q.topic===filter.topic)&&(!needle||(q.prompt+' '+q.options.join(' ')+' '+q.topic).toLowerCase().includes(needle)));}
function progress(){const wrong=wrongQuestions();return `${intro('СВОЙ ТЕМП, СВОЙ РЕЗУЛЬТАТ','Мой прогресс','Смотри, какие темы уже понятны, и возвращайся к ошибкам. Данные сохраняются в этом браузере; между устройствами они не синхронизируются.')}<div class="stats"><div class="stat"><strong>${masteredCount()}</strong><span>последних<br>верных ответов</span></div><div class="stat"><strong>${wrong.length}</strong><span>вопросов<br>с ошибками</span></div><div class="stat"><strong>${state.read.length}/5</strong><span>конспектов<br>прочитано</span></div><div class="stat"><strong>${state.history.length}</strong><span>завершённых<br>попыток*</span></div></div><div class="two-col"><section class="card"><h2>Пять паттернов финала</h2>${CORE.map(t=>{const list=DATA.questions.filter(q=>q.topic===t&&q.finalCore),n=list.filter(q=>state.outcomes[q.id]?.correct).length;return `<div class="bar-row"><span>${t}</span><div class="progress-track"><div class="progress-fill" style="width:${100*n/list.length}%"></div></div><span class="muted">${n}/${list.length}</span></div>`;}).join('')}<p class="small muted">Число вопросов с верным последним ответом / всего вопросов по теме.</p></section><section class="card"><h2>Повтори сложное</h2><p style="margin:13px 0 20px">${wrong.length?'В подборке '+wrong.length+' вопросов. После правильного ответа вопрос исчезнет из списка ошибок.':'Ошибок пока нет. Пройди любой квиз, и здесь появятся вопросы, которые стоит повторить.'}</p>${wrong.length?button('Работа над ошибками →','mistakes','','primary'):'<a href="#quizzes" class="button primary">Выбрать квиз →</a>'}</section></div><div class="section-head"><h2>Последние попытки</h2></div><section class="card">${state.history.length?state.history.map(h=>`<div class="history-item"><span><strong>${esc(h.title)}</strong><br><span class="small muted">${new Date(h.date).toLocaleString('ru-RU')} · ${h.mode==='exam'?'Экзамен':'Практика'}</span></span><strong>${h.correct}/${h.total} · ${h.percent}%</strong></div>`).join(''):'<p class="muted">Заверши первый квиз — результат появится здесь.</p>'}</section><p class="source-note">* Храним последние 20 завершённых попыток. Незавершённый квиз можно продолжить с главной страницы.</p><div class="actions" style="margin-top:25px">${button('Сбросить мой прогресс','reset','','danger')}</div>`;}
function questionView(){const s=state.session;if(!s)return `<div class="empty"><h3>Квиз ещё не выбран</h3><p>Начни с одной из подборок.</p><a href="#quizzes" class="button primary">Выбрать квиз →</a></div>`;const q=s.questions[s.index],selected=s.answers[q.id],checked=!!s.checked[q.id]&&s.mode==='practice';return `<a href="#quizzes" class="back">← К подборкам (текущая попытка сохранится)</a><div class="page-intro"><div class="eyebrow">${s.mode==='exam'?'ПРОБНЫЙ ЭКЗАМЕН':'РЕЖИМ ОБУЧЕНИЯ'}</div><h2>${esc(s.title)}</h2></div><div class="quiz-layout"><section class="quiz-main"><div class="quiz-top"><span>Вопрос <strong>${s.index+1}</strong> из ${s.questions.length}</span><span class="tag purple">${esc(q.topic)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${100*(s.index+1)/s.questions.length}%"></div></div><div class="question" lang="en">${esc(q.prompt)}</div><div class="options" role="group" aria-label="Варианты ответа">${q.options.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&selected===i&&i!==q.answer?'wrong':''}" data-action="answer" data-value="${i}" aria-pressed="${selected===i}" ${checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span class="option-text" lang="en">${esc(o)}</span></button>`).join('')}</div>${checked?feedback(q,selected):''}<div class="quiz-controls"><button class="button" data-action="prev" ${s.index===0?'disabled':''}>← Назад</button><div class="actions">${s.mode==='practice'&&!checked?`<button class="button primary" data-action="check" ${selected===undefined?'disabled':''}>Проверить</button>`:''}${s.index<s.questions.length-1?button(checked||s.mode==='exam'?'Далее →':'Пропустить →','next','',''+(checked||s.mode==='exam'?'primary':'')):button('Завершить','finish','','primary')}</div></div></section><aside class="quiz-side">${s.mode==='exam'?'<div class="small muted">Осталось времени</div><div id="timer" class="timer"></div>':'<div class="eyebrow">БЕЗ СПЕШКИ</div><p class="small muted">После проверки ответ фиксируется. Для новой попытки запусти подборку ещё раз.</p>'}<p class="small muted">Отвечено: ${Object.keys(s.answers).length}/${s.questions.length}</p><div class="palette" aria-label="Навигация по вопросам">${s.questions.map((item,i)=>`<button data-action="jump" data-value="${i}" class="${s.answers[item.id]!==undefined?'answered':''} ${i===s.index?'current':''}" aria-label="Вопрос ${i+1}${s.answers[item.id]!==undefined?', есть ответ':''}" ${i===s.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="small muted">${s.mode==='exam'?'Можно менять ответы до завершения. Таймер продолжает идти при закрытии вкладки.':'Нажми номер, чтобы вернуться к вопросу.'}</p>${button('Завершить попытку','finish')}</aside></div>`;}
function feedback(q,selected){const correct=selected===q.answer;return `<div class="feedback ${correct?'':'incorrect'}" role="status"><h3>${correct?'✓ Верно':'Пока неверно — разберёмся'}</h3><p>${esc(q.explanation)}</p><p class="small">${esc(q.source)}${q.answerSource==='inferred'?' · Ключ восстановлен при подготовке сайта, в исходном файле его не было.':''}</p></div>`;}
function review(q,selected,i){const ok=selected===q.answer;return `<details class="review"><summary><span class="status-icon ${ok?'':'bad'}">${ok?'✓':'×'}</span><span><strong>${i+1}. ${esc(q.topic)}</strong> · ${esc(q.prompt.split('\n')[0].slice(0,135))}${q.prompt.split('\n')[0].length>135?'…':''}</span></summary><div class="review-body"><div class="question" lang="en">${esc(q.prompt)}</div>${!ok?`<div class="answer-line bad">Ваш ответ: ${selected===undefined?'не выбран':esc(q.options[selected])}</div>`:''}<div class="answer-line">Верный ответ: ${esc(q.options[q.answer])}</div><p style="margin-top:13px">${esc(q.explanation)}</p><p class="source-note">${esc(q.source)}${q.answerSource==='inferred'?' · Восстановленный ключ':''}</p></div></details>`;}
function result(){const s=state.result;if(!s)return notFound();const score=scoreSession(s);return `<a class="back" href="#quizzes">← Все квизы</a><div class="result-hero"><div class="score-circle"><strong>${score.percent}%</strong><span>${score.correct} из ${score.total}</span></div><div class="result-copy"><div class="eyebrow">ПОПЫТКА ЗАВЕРШЕНА</div><h1>${score.percent>=80?'Хорошая работа!':'Теперь понятно, что повторить'}</h1><p>${esc(s.title)}<br>${score.unanswered?'Без ответа: '+score.unanswered+'. ':''}${s.mode==='exam'?'Тренировочная оценка: '+score.points+' / 80. Это не официальный результат.':'Открой любой вопрос ниже, чтобы посмотреть разбор.'}</p><div class="actions">${button('Пройти заново','retry','','primary')}${score.correct<score.total?button('Повторить ошибки этой попытки','retry-wrong'):''}<a class="button" href="#lectures">К конспектам</a></div></div></div><div class="section-head"><h2>Разбор ответов</h2><span class="small muted">Нажми на вопрос</span></div>${s.questions.map((q,i)=>review(q,s.answers[q.id],i)).join('')}`;}
function notFound(){return '<div class="empty"><h3>Раздел не найден</h3><a href="#home" class="button primary">На главную</a></div>';}
function render(){const route=location.hash.slice(1)||'home';const [page,id]=route.split('/');let html;switch(page){case'home':html=home();break;case'lectures':html=lectures();break;case'lecture':html=lecture(id);break;case'quizzes':html=quizzes(id==='generated');break;case'progress':html=progress();break;case'quiz':html=questionView();break;case'result':html=result();break;default:html=notFound();}$('#content').innerHTML=html;document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===(page==='lecture'?'lectures':page==='quiz'||page==='result'?'quizzes':page);el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});if(page==='quizzes')filteredQuestions();updateTimer();if(!storageOK&&!$('#storage-warning'))$('#content').insertAdjacentHTML('afterbegin','<div class="info-strip" id="storage-warning">Сохранение в браузере недоступно. Не закрывайте вкладку, если хотите сохранить текущую попытку.</div>');}
function ask(title,text,action){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${esc(title)}</h2><p>${esc(text)}</p><div class="actions">${button('Отмена','cancel')}${button('Подтвердить',action,'','primary')}</div></section></div>`;$('#modal-root .button').focus();}
function start(questions,title,mode='practice',force=false){if(state.session&&!force){pendingStart={questions,title,mode};ask('Начать новую попытку?','Текущая незавершённая попытка будет заменена. Уже проверенные ответы останутся в прогрессе.','replace-session');return;}state.session=createSession(questions,title,mode);save();go('quiz');}
let pendingStart=null;
function record(q,correct){const prev=state.outcomes[q.id];state.outcomes[q.id]={correct,attempts:(prev?.attempts||0)+1};}
function finish(timedOut=false){const s=state.session;if(!s)return;for(const q of s.questions){if(s.mode==='exam'||!s.checked[q.id])record(q,s.answers[q.id]===q.answer);}const score=scoreSession(s);state.history.unshift({title:s.title,mode:s.mode,date:Date.now(),...score});state.history=state.history.slice(0,20);state.result={...s,finishedAt:Date.now()};state.session=null;save();$('#modal-root').innerHTML='';go('result');if(timedOut)toast('Время закончилось. Попытка завершена автоматически.');}
function updateTimer(){const s=state.session;if(!s||s.mode!=='exam')return;const secs=remainingSeconds(s.deadline);if(!secs){finish(true);return;}const el=$('#timer');if(el){el.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;el.classList.toggle('urgent',secs<=300);}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const a=target.dataset.action,v=target.dataset.value,s=state.session;switch(a){case'resume':go('quiz');break;case'exam':start(examQuestions(DATA.questions),'Пробный финал · 5 паттернов','exam');break;case'set':{const set=DATA.sets.find(x=>x.id===v);start(DATA.questions.filter(q=>q.set===v),set.title);break;}case'lecture-quiz':start(DATA.questions.filter(q=>q.lecture===v),'Лекция '+DATA.lectures.find(l=>l.id===v).number+' · новые вопросы');break;case'core':start(DATA.questions.filter(q=>q.finalCore&&CORE.includes(q.topic)),'Пять паттернов · практика');break;case'filtered':start(filterPool(),'Подборка по поиску');break;case'single':start([questionsById.get(v)],'Практика одного вопроса');break;case'mistakes':start(wrongQuestions(),'Работа над ошибками');break;case'read':state.read=state.read.includes(v)?state.read.filter(x=>x!==v):[...state.read,v];save();render();toast(state.read.includes(v)?'Лекция отмечена как прочитанная':'Отметка снята');break;case'answer':if(s&&!s.checked[s.questions[s.index].id]){s.answers[s.questions[s.index].id]=Number(v);save();render();}break;case'check':if(s){const q=s.questions[s.index];if(Number.isInteger(s.answers[q.id])&&!s.checked[q.id]){s.checked[q.id]=true;record(q,s.answers[q.id]===q.answer);save();render();}}break;case'next':case'prev':case'jump':if(s){s.index=Math.max(0,Math.min(s.questions.length-1,a==='jump'?Number(v):s.index+(a==='next'?1:-1)));save();render();window.scrollTo(0,0);}break;case'finish':if(s){const n=scoreSession(s).unanswered;ask('Завершить попытку?',n?`${n} вопросов без ответа. Они будут засчитаны как неверные. Можно отменить и вернуться к ним.`:'После завершения откроется результат и разбор всех вопросов.','confirm-finish');}break;case'confirm-finish':finish();break;case'cancel':$('#modal-root').innerHTML='';pendingStart=null;break;case'replace-session':if(pendingStart){const p=pendingStart;pendingStart=null;$('#modal-root').innerHTML='';start(p.questions,p.title,p.mode,true);}break;case'retry':if(state.result){const r=state.result;start(r.mode==='exam'?examQuestions(DATA.questions):r.questions.map(q=>questionsById.get(q.id)),r.title,r.mode);}break;case'retry-wrong':if(state.result){const r=state.result;start(r.questions.filter(q=>r.answers[q.id]!==q.answer).map(q=>questionsById.get(q.id)),'Ошибки последней попытки');}break;case'reset':ask('Сбросить прогресс?','Отметки лекций, история, ошибки и текущая попытка будут удалены только из этого браузера.','confirm-reset');break;case'confirm-reset':state=emptyState();save();$('#modal-root').innerHTML='';render();toast('Прогресс сброшен');break;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter.text=e.target.value;filteredQuestions();}});
document.addEventListener('change',e=>{if(e.target.id==='topic'){filter.topic=e.target.value;filteredQuestions();}});
document.addEventListener('keydown',e=>{const modal=$('#modal-root .modal');if(!modal)return;if(e.key==='Escape'){$('#modal-root').innerHTML='';pendingStart=null;}if(e.key==='Tab'){const buttons=[...modal.querySelectorAll('button')];const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('#content').focus();$('#content').scrollIntoView();});
setInterval(updateTimer,1000);
render();
